test('role definitions include all required roles and proprietor is highest', () => { assert.equal(ROLE_DEFINITIONS.length, 25); assert.equal(ROLE_DEFINITIONS.find((r) => r.roleKey === 'PROPRIETOR').oversightRank, 100); assert.ok(ROLE_KEYS.has('PARENT')); assert.ok(ROLE_KEYS.has('STUDENT')); assert.ok(ROLE_KEYS.has('PROCUREMENT_OFFICER')); assert.ok(ROLE_KEYS.has('PROPERTY_MANAGER')); assert.ok(ROLE_KEYS.has('COMPLIANCE_OFFICER')); assert.ok(ROLE_KEYS.has('DATA_PROTECTION_OFFICER')); });
test('sidebar registry filters by permission and sorts modules', () => { const groups = visibleSidebar({ permissions: new Set(['users.read']) }); assert.equal(groups.length, 2); const system = groups.find((group) => group.category === 'ADMINISTRATIVE'); assert.ok(system.modules.some((module) => module.moduleKey === 'users')); assert.equal(groups.at(-1).category, 'SYSTEM & SECURITY'); assert.equal(SIDEBAR_CATEGORIES.length, 20); });
test('sidebar registry accepts a future module without editing navigation code', () => { const groups = visibleSidebar({ modules: [{ moduleKey: 'fees', moduleName: 'Fees', category: 'FEE HUB', route: '/fees', icon: '$', displayOrder: 1, requiredPermission: null, enabled: true }], permissions: new Set() }); assert.equal(groups[0].modules[0].moduleKey, 'fees'); });
test('audit logs require action and entity and are immutable-style', () => { const log = createAuditLog({ action: 'UPDATE', entity: 'School', entityId: 'school-1', previousValue: { name: 'Old' }, newValue: { name: 'New' } }, () => '2026-09-02T00:00:00.000Z'); assert.equal(log.occurredAt, '2026-09-02T00:00:00.000Z'); assert.throws(() => { log.action = 'DELETE'; }, TypeError); assert.throws(() => createAuditLog({ action: 'READ' }), /entity/); });
test('foundation schema contains relational anchors and audit indexes', async () => { const schema = await readFile(new URL('../schema/001_foundation.sql', import.meta.url), 'utf8'); const studentSchema = await readFile(new URL('../schema/003_students_admissions.sql', import.meta.url), 'utf8'); const communicationSchema = await readFile(new URL('../schema/010_communication.sql', import.meta.url), 'utf8'); for (const table of ['schools', 'academic_years', 'terms', 'levels', 'classes', 'streams', 'subjects', 'departments', 'houses', 'users', 'roles', 'permissions', 'user_roles', 'sidebar_modules', 'sidebar_categories', 'system_settings', 'audit_logs', 'students', 'staff']) assert.match(schema, new RegExp(`CREATE TABLE IF NOT EXISTS ${table}`)); for (const table of ['student_profiles', 'student_family_contacts', 'student_health_records', 'student_documents', 'student_class_history', 'parent_student_links', 'admission_applications']) assert.match(studentSchema, new RegExp(`CREATE TABLE IF NOT EXISTS ${table}`)); for (const table of ['announcements', 'notifications', 'messages', 'calendar_events', 'notification_preferences', 'communication_delivery_log']) assert.match(communicationSchema, new RegExp(`CREATE TABLE IF NOT EXISTS ${table}`)); assert.match(schema, /REFERENCES schools\(id\)/); assert.match(schema, /idx_audit_entity/); });
test('foundation seed preserves official school identity and registry categories', async () => { const seed = await readFile(new URL('../schema/002_foundation_seed.sql', import.meta.url), 'utf8'); assert.match(seed, /OSAAH DAYLIGHT SCH\. COM\./); assert.match(seed, /AIM HIGH, ACADEMIC IS OUR CORE VALUE/); assert.match(seed, /school-osaah-daylight/); assert.equal((seed.match(/UNION ALL SELECT/g) ?? []).length, 19); });
test('mobile-first shell includes exactly two portal cards', async () => { const html = await readFile(new URL('../public/index.html', import.meta.url), 'utf8'); const css = await readFile(new URL('../public/styles.css', import.meta.url), 'utf8'); assert.equal((html.match(/class="portal-card"/g) ?? []).length, 2); assert.match(html, /PARENT PORTAL/); assert.match(html, /SCHOOL PORTAL/); assert.match(html, /name="viewport"/); assert.match(css, /min-width:320px/); assert.match(css, /@media\(min-width:760px\)/); assert.match(css, /\.sidebar\{/); });
test('official logo asset is present and referenced without replacement', async () => { const logo = await readFile(new URL('../public/assets/osaah-daylight-logo.png', import.meta.url)); const html = await readFile(new URL('../public/index.html', import.meta.url), 'utf8'); assert.equal(logo[0], 0x89); assert.equal(logo[1], 0x50); assert.match(html, /assets\/osaah-daylight-logo\.png/); });
test('parent and school logins are separated by portal and expose authorized children', () => { const auth = createAuthService(); const parent = auth.login({ username: 'parent@example.com', password: 'Parent123!', portal: 'parent' }); const school = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); assert.equal(parent.ok, true); assert.equal(parent.user.roleKey, 'PARENT'); assert.equal(school.ok, true); assert.equal(school.user.roleKey, 'TEACHER'); assert.equal(auth.login({ username: 'parent@example.com', password: 'Parent123!', portal: 'school' }).ok, false); assert.equal(auth.authenticate(parent.token).children.length, 2); assert.deepEqual(auth.authenticate(parent.token).authorizedStaffIds, ['user-teacher-1']); });
test('school authentication returns generic failures, canonical dashboard redirects, and no password material', () => { const auth = createAuthService(); const valid = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); assert.equal(valid.ok, true); assert.equal(valid.redirectTo, '/academics'); assert.equal(valid.user.role, 'TEACHER'); assert.equal(Object.hasOwn(valid.user, 'password'), false); assert.equal(Object.hasOwn(valid.user, 'passwordHash'), false); assert.equal(auth.login({ username: 'teacher@osaah.edu.gh', password: 'wrong', portal: 'school' }).error, 'Incorrect username or password.'); assert.equal(auth.login({ username: 'missing@example.com', password: 'wrong', portal: 'school' }).error, 'Incorrect username or password.'); assert.equal(auth.login({ username: 'teacher@osaah.edu.gh', portal: 'school' }).error, 'Incorrect username or password.'); });
test('disabled and revoked accounts cannot log in or continue an existing session', () => { const users = DEMO_USERS.map((user) => ({ ...user, permissions: new Set(user.permissions) })); const auth = createAuthService({ users }); const session = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); assert.equal(auth.setAccountStatus('user-teacher-1', false), true); assert.equal(auth.authenticate(session.token), null); assert.equal(auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }).error, 'Incorrect username or password.'); });
test('administrator management uses proprietor-only access, secure credentials, replacement history, and revocation', async () => { const events = []; const auth = createAuthService({ audit: (event) => events.push(event) }); const proprietor = auth.login({ username: 'proprietor@osaah.edu.gh', password: 'Proprietor123!', portal: 'school' }); const first = auth.createAdministrator({ fullName: 'Ama Admin', staffId: 'STAFF-ADMIN-001', email: 'ama.admin@osaah.edu.gh' }, { id: 'user-proprietor-1', schoolId: 'school-osaah-daylight' }); assert.match(first.administrator.username, /@osaah\.edu\.gh$/); assert.ok(first.temporaryPassword); assert.equal(auth.login({ username: first.administrator.username, password: first.temporaryPassword, portal: 'school' }).redirectTo, '/settings'); assert.equal(auth.listAdministrators('school-osaah-daylight')[0].temporaryPassword, undefined); const second = auth.createAdministrator({ fullName: 'Kojo Admin', staffId: 'STAFF-ADMIN-002' }, { id: 'user-proprietor-1', schoolId: 'school-osaah-daylight' }); assert.equal(auth.listAdministrators('school-osaah-daylight').find((item) => item.userId === first.administrator.id).status, 'REASSIGNED'); assert.equal(auth.login({ username: first.administrator.username, password: first.temporaryPassword, portal: 'school' }).ok, false); assert.equal(auth.revokeAccount(second.administrator.id), true); assert.equal(auth.login({ username: second.administrator.username, password: second.temporaryPassword, portal: 'school' }).error, 'Incorrect username or password.'); assert.ok(events.some((event) => event.action === 'LOGIN_SUCCESS')); assert.ok(events.some((event) => event.action === 'SESSION_REVOKED')); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (path, token) => new Promise((resolve, reject) => { const req = httpRequest({ port, path, headers: token ? { Authorization: `Bearer ${token}` } : {} }, (res) => { res.resume(); res.on('end', () => resolve(res.statusCode)); }); req.on('error', reject); req.end(); }); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); assert.equal(await request('/api/administrators', proprietor.token), 200); assert.equal(await request('/api/administrators', teacher.token), 403); assert.equal(await request('/administrator-management', teacher.token), 403); await new Promise((resolve) => server.close(resolve)); });
test('sessions expire and failed login protection activates', () => { let clock = 1000; const auth = createAuthService({ now: () => clock }); for (let i = 0; i < 5; i += 1) auth.login({ username: 'teacher@osaah.edu.gh', password: 'wrong', portal: 'school' }); assert.equal(auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }).status, 429); const valid = auth.login({ username: 'proprietor@osaah.edu.gh', password: 'Proprietor123!', portal: 'school' }); clock += 1_800_001; assert.equal(auth.authenticate(valid.token), null); });
test('password reset tokens are single-use and invalidate existing sessions', () => { const auth = createAuthService(); const session = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); const reset = auth.requestPasswordReset('teacher@osaah.edu.gh'); assert.equal(auth.completePasswordReset(reset.token, 'NewTeacher123!').ok, true); assert.equal(auth.authenticate(session.token), null); assert.equal(auth.login({ username: 'teacher@osaah.edu.gh', password: 'NewTeacher123!', portal: 'school' }).ok, true); assert.equal(auth.completePasswordReset(reset.token, 'Another123!').ok, false); });
test('protected API rejects anonymous users and enforces role restrictions', async () => { const auth = createAuthService(); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (path, options = {}) => new Promise((resolve, reject) => { const req = httpRequest({ port, path, method: options.method ?? 'GET', headers: options.headers ?? {} }, (res) => { let body = ''; res.on('data', (chunk) => { body += chunk; }); res.on('end', () => resolve({ status: res.statusCode, body, headers: res.headers })); }); req.on('error', reject); if (options.body) req.write(options.body); req.end(); }); const anonymous = await request('/api/management'); assert.equal(anonymous.status, 401); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); const forbidden = await request('/api/management', { headers: { Authorization: `Bearer ${teacher.token}` } }); assert.equal(forbidden.status, 403); const proprietor = auth.login({ username: 'proprietor@osaah.edu.gh', password: 'Proprietor123!', portal: 'school' }); const allowed = await request('/api/management', { headers: { Authorization: `Bearer ${proprietor.token}` } }); assert.equal(allowed.status, 200); await new Promise((resolve) => server.close(resolve)); });
test('specialist roles receive only their registered modules', () => { const cases = [['ACCOUNTANT_BURSAR', ['fees', 'fee-structure', 'invoices', 'student-fees', 'payments', 'receipts', 'arrears', 'discounts', 'fee-statements', 'finance', 'finance-reports', 'income', 'expenses', 'cashbook', 'budgets']], ['LIBRARIAN', ['library', 'books', 'borrowing', 'returns', 'library-reports']], ['TRANSPORT_MANAGER', ['transport', 'transport-routes', 'vehicles', 'drivers', 'routes', 'transport-students', 'trips', 'transport-fees']]]; for (const [roleKey, moduleKeys] of cases) { const groups = visibleSidebar({ permissions: new Set(['fees.read', 'finance.read', 'library.read', 'transport.read']), roleKey }); const keys = groups.flatMap((group) => group.modules.map((module) => module.moduleKey)); for (const key of moduleKeys) assert.ok(keys.includes(key)); assert.equal(keys.at(-1), 'logout'); } });
test('student creation generates a permanent unique ID and rejects duplicate admission numbers', () => { const service = createStudentService({ now: () => '2026-09-02T00:00:00.000Z' }); const first = service.createStudent({ admissionNumber: 'ADM-001', firstName: 'Ama', surname: 'Mensah', classId: 'primary-4' }); const second = service.createStudent({ admissionNumber: 'ADM-002', firstName: 'Kojo', surname: 'Mensah' }); assert.equal(first.id, 'STD-000001'); assert.equal(second.id, 'STD-000002'); assert.equal(first.qrCode, 'osaah:student:STD-000001'); assert.equal(first.history.length, 1); assert.throws(() => service.createStudent({ admissionNumber: 'ADM-001', firstName: 'Duplicate', surname: 'Student' }), /already exists/); });
test('student history preserves identity across class assignment and links multiple parents', () => { const service = createStudentService(); const student = service.createStudent({ firstName: 'Esi', surname: 'Owusu' }); service.assignClass(student.id, { classId: 'primary-5', academicYearId: '2026' }); service.assignClass(student.id, { classId: 'jhs-1', academicYearId: '2027', reason: 'PROMOTION' }); service.linkParent(student.id, { parentId: 'parent-1', relationship: 'Mother', telephone: '0240000000' }); const links = service.linkParent(student.id, { parentId: 'parent-2', relationship: 'Father' }); const record = service.getStudent(student.id); assert.equal(record.id, student.id); assert.equal(record.history.length, 2); assert.equal(links.length, 2); });
test('student search supports parent phone and assigned-student RBAC', () => { const service = createStudentService(); const assigned = service.createStudent({ firstName: 'Yaw', surname: 'Boateng', family: [{ telephone: '0241111111' }] }); service.createStudent({ firstName: 'Akua', surname: 'Darko', family: [{ telephone: '0242222222' }] }); assert.equal(service.search('0241111111', { roleKey: 'TEACHER', assignedStudentIds: [assigned.id] }).length, 1); assert.equal(service.search('0242222222', { roleKey: 'TEACHER', assignedStudentIds: [assigned.id] }).length, 0); });
test('admissions workflow enforces order and generates offer and enrollment documents', () => { const service = createStudentService(); const application = service.createAdmission({ applicantName: 'Adwoa' }); let current = application; for (const stage of ADMISSION_STAGES.slice(1)) current = service.advanceAdmission(application.applicationNumber, stage); assert.equal(current.stage, 'CLASS_ASSIGNMENT'); assert.equal(current.admissionLetter, `ADMISSION-OFFER-${application.applicationNumber}`); assert.equal(current.enrollmentConfirmation, `ENROLLMENT-${application.applicationNumber}`); assert.throws(() => service.advanceAdmission(application.applicationNumber, 'ENROLLMENT'), /Invalid admission transition/); });
test('student levels cover the required structure and sidebar modules register automatically', () => { assert.deepEqual(CORE_LEVELS.slice(0, 2), ['KG1', 'KG2']); assert.equal(CORE_LEVELS.at(-1), 'JHS 3'); const studentGroup = visibleSidebar({ permissions: new Set(['students.read']), roleKey: 'TEACHER' }).find((group) => group.category === 'STUDENTS MANAGEMENT'); const admissionsGroup = visibleSidebar({ permissions: new Set(['admissions.read']), roleKey: 'ADMISSIONS_OFFICER' }).find((group) => group.category === 'ADMISSIONS'); assert.equal(studentGroup.modules[0].moduleKey, 'student-profiles'); assert.equal(admissionsGroup.modules[0].moduleKey, 'admissions'); });
test('attendance records support statuses, methods, summaries, and duplicate protection', () => { const service = createAttendanceService(); const actor = { userId: 'teacher-1' }; assert.ok(STUDENT_STATUSES.includes('LATE')); assert.ok(ATTENDANCE_METHODS.includes('QR_CODE')); service.saveStudentAttendance({ date: '2026-09-02', classId: 'primary-4', studentId: 'student-1', status: 'PRESENT', method: 'QR_CODE' }, actor); service.saveStudentAttendance({ date: '2026-09-02', classId: 'primary-4', studentId: 'student-2', status: 'LATE' }, actor); assert.equal(service.summary({ date: '2026-09-02', classId: 'primary-4' }).attendancePercentage, 100); assert.throws(() => service.saveStudentAttendance({ date: '2026-09-02', classId: 'primary-4', studentId: 'student-1', status: 'ABSENT' }, actor), /already recorded/); });
test('attendance corrections and offline sync reject stale overwrites', () => { const service = createAttendanceService(); const actor = { userId: 'teacher-1' }; const entry = { date: '2026-09-02', studentId: 'student-1', status: 'PRESENT' }; const current = service.saveStudentAttendance(entry, actor); service.saveStudentAttendance({ ...entry, status: 'LATE' }, actor, { correction: true, expectedVersion: current.version }); assert.throws(() => service.saveStudentAttendance({ ...entry, status: 'ABSENT' }, actor, { correction: false, expectedVersion: 1 }), /already recorded/); assert.throws(() => service.saveStudentAttendance({ ...entry, status: 'ABSENT' }, actor, { correction: true, expectedVersion: 1 }), /newer/); });
test('examinations calculate weighted marks and configurable grades', () => { const service = createExaminationService(); assert.equal(service.calculateMarks(85, 50).weightedMarks, 42.5); assert.equal(service.calculateMarks(85, 100).grade, 'A'); service.setGradingSystem('custom', [{ min: 90, grade: 'Distinction', remark: 'Outstanding' }, { min: 0, grade: 'Pass', remark: 'Pass' }]); assert.equal(service.calculateMarks(92, 100, 'custom').grade, 'Distinction'); assert.equal(DEFAULT_GRADING.length, 5); });
test('examination result publication is ordered and corrections are authorized', () => { const service = createExaminationService(); const exam = service.createExamination({ name: 'End of Term', type: 'END_OF_TERM' }); const actor = { userId: 'teacher', canApprove: true, canCorrect: true }; const mark = service.enterMarks({ examId: exam.id, studentId: 'student-1', subjectId: 'math', rawMarks: 75 }, actor); for (const state of RESULT_STATES.slice(1)) service.transitionResult(exam.id, 'student-1', 'math', state, actor); assert.throws(() => service.enterMarks({ examId: exam.id, studentId: 'student-1', subjectId: 'math', rawMarks: 60 }, { userId: 'teacher' }), /locked/); const corrected = service.enterMarks({ examId: exam.id, studentId: 'student-1', subjectId: 'math', rawMarks: 60 }, actor, { correction: true }); assert.equal(corrected.state, 'DRAFT'); assert.ok(mark.id); });
test('promotion decisions preserve history and support all outcomes', () => { const service = createExaminationService(); const record = service.promote('student-1', '2026', 'PROMOTED', { userId: 'headteacher' }, 'Ready for next level'); assert.ok(PROMOTION_DECISIONS.includes(record.decision)); assert.equal(record.studentId, 'student-1'); });
test('examination modules register under the results category and mobile score entry is responsive', async () => { const group = visibleSidebar({ permissions: new Set(['examinations.read', 'marks.write', 'results.read', 'promotion.write']), roleKey: 'PROPRIETOR' }).find((item) => item.category === 'EXAMINATIONS & RESULTS'); for (const key of ['examinations', 'marks-entry', 'results', 'promotion', 'exam-timetable', 'broadsheets', 'report-cards', 'promotion-results']) assert.ok(group.modules.some((module) => module.moduleKey === key)); const html = await readFile(new URL('../public/examinations.html', import.meta.url), 'utf8'); const css = await readFile(new URL('../public/styles.css', import.meta.url), 'utf8'); assert.match(html, /score-grid/); assert.match(css, /\.score-grid\{/); });
test('fees calculate invoices server-side and generate unique receipts', () => { const service = createFeeService(); const invoice = service.invoice({ studentId: 'student-1', parentUserId: 'parent-1', lineItems: [{ type: 'TUITION', amount: 1000 }, { type: 'ICT', amount: 100 }], discount: 100 }); const payment = service.pay({ invoiceNumber: invoice.invoiceNumber, amount: 500, method: 'MOBILE_MONEY' }, { userId: 'bursar-1' }); assert.equal(invoice.total, 1000); assert.equal(payment.balance, 500); assert.match(payment.receiptNumber, /^RCT-/); assert.ok(FEE_TYPES.includes('TRANSPORT')); assert.ok(PAYMENT_METHODS.includes('PAYMENT_GATEWAY')); });
test('refunds, reversals, and cancellations preserve receipt audit state', () => { const service = createFeeService(); const invoice = service.invoice({ studentId: 'student-1', lineItems: [{ type: 'TUITION', amount: 500 }] }); const payment = service.pay({ invoiceNumber: invoice.invoiceNumber, amount: 500, method: 'CASH' }, { userId: 'bursar-1' }); const refunded = service.changeReceipt(payment.receiptNumber, 'REFUND', { userId: 'proprietor-1' }, 'Duplicate payment'); assert.equal(refunded.status, 'REFUNDED'); assert.equal(service.statement('student-1').invoices[0].balance, 500); assert.throws(() => service.changeReceipt(payment.receiptNumber, 'REVERSE', { userId: 'bursar-1' }), /already changed/); });
test('fee statements can be isolated to a parent and gateway config exposes no secret', () => { const service = createFeeService(); const first = service.invoice({ studentId: 'student-1', parentUserId: 'parent-1', lineItems: [{ type: 'BOOKS', amount: 20 }] }); const second = service.invoice({ studentId: 'student-1', parentUserId: 'parent-2', lineItems: [{ type: 'BOOKS', amount: 30 }] }); service.pay({ invoiceNumber: first.invoiceNumber, amount: 20, method: 'CASH' }, { userId: 'bursar-1' }); service.pay({ invoiceNumber: second.invoiceNumber, amount: 30, method: 'CASH' }, { userId: 'bursar-1' }); assert.equal(service.statement('student-1', 'parent-1').invoices[0].invoiceNumber, first.invoiceNumber); assert.equal(service.statement('student-1', 'parent-1').payments.length, 1); assert.equal(service.statement('student-2', 'parent-1').invoices.length, 0); assert.deepEqual(service.configureGateway('mobile-money', { merchantName: 'OsaaH' }), { name: 'mobile-money', publicConfig: { merchantName: 'OsaaH' } }); });
test('fee and finance modules register in their own sidebar categories and mobile views exist', async () => { const feeGroup = visibleSidebar({ permissions: new Set(['fees.read']), roleKey: 'ACCOUNTANT_BURSAR' }).find((group) => group.category === 'FEE HUB'); const financeGroup = visibleSidebar({ permissions: new Set(['finance.read']), roleKey: 'ACCOUNTANT_BURSAR' }).find((group) => group.category === 'FINANCE'); for (const key of ['fees', 'fee-structure', 'invoices', 'student-fees', 'payments', 'receipts', 'arrears', 'discounts', 'fee-statements']) assert.ok(feeGroup.modules.some((module) => module.moduleKey === key)); for (const key of ['finance', 'finance-reports', 'income', 'expenses', 'cashbook', 'budgets']) assert.ok(financeGroup.modules.some((module) => module.moduleKey === key)); assert.match(await readFile(new URL('../public/fees.html', import.meta.url), 'utf8'), /viewport/); assert.match(await readFile(new URL('../public/finance.html', import.meta.url), 'utf8'), /FINANCE/); });
test('staff profiles isolate confidential fields and preserve assignments', () => { const service = createStaffService(); const created = service.createProfile({ fullName: 'Aba Teacher', roleKey: 'TEACHER', confidential: { salary: 3000 } }); assert.equal(service.getProfile(created.id).confidential, undefined); assert.equal(service.getProfile(created.id, { confidential: true }).confidential.salary, 3000); const assignment = service.assign(created.id, { classId: 'primary-4', subjectId: 'math', streamId: 'a' }); assert.equal(assignment.staffId, created.id); });
test('staff leave supports application and authorized decision history', () => { const service = createStaffService(); const member = service.createProfile({ fullName: 'Kofi Staff' }); const request = service.applyLeave({ staffId: member.id, leaveType: 'ANNUAL', startsOn: '2026-09-10', endsOn: '2026-09-12' }); assert.equal(request.state, 'PENDING'); const approved = service.decideLeave(request.id, 'APPROVED', { userId: 'hr-1' }); assert.equal(approved.state, 'APPROVED'); assert.ok(LEAVE_STATES.includes(approved.state)); assert.throws(() => service.decideLeave(request.id, 'PENDING', { userId: 'hr-1' }), /Invalid/); });
test('staff modules register under STAFF MANAGEMENT and mobile leave/profile views exist', async () => { const group = visibleSidebar({ permissions: new Set(['staff.read', 'hr.read', 'leave.read', 'staff.attendance.read']), roleKey: 'HR_OFFICER' }).find((item) => item.category === 'STAFF MANAGEMENT'); assert.ok(group.modules.some((module) => module.moduleKey === 'staff-directory')); assert.ok(group.modules.some((module) => module.moduleKey === 'hr-documents')); assert.match(await readFile(new URL('../public/staff.html', import.meta.url), 'utf8'), /viewport/); assert.match(await readFile(new URL('../public/leave.html', import.meta.url), 'utf8'), /Submit Leave Request/); });
test('communication enforces child relationships for parent and teacher messages', () => { const service = createCommunicationService(); const parent = { userId: 'parent-1', roleKey: 'PARENT', children: [{ id: 'student-1' }] }; const teacher = { userId: 'teacher-1', roleKey: 'TEACHER' }; const message = service.sendMessage({ recipientId: 'teacher-1', studentId: 'student-1', body: 'Hello' }, parent, { authorizedStudentIds: ['student-1'], authorizedRecipientIds: ['teacher-1'] }); assert.equal(message.status, 'SENT'); assert.throws(() => service.sendMessage({ recipientId: 'other-staff', studentId: 'student-1', body: 'No access' }, parent, { authorizedStudentIds: ['student-1'], authorizedRecipientIds: ['teacher-1'] }), /authorized/); assert.throws(() => service.sendMessage({ recipientId: 'teacher-1', studentId: 'student-2', body: 'No access' }, parent, { authorizedStudentIds: ['student-1'], authorizedRecipientIds: ['teacher-1'] }), /authorized/); assert.throws(() => service.sendMessage({ recipientId: 'other-parent', studentId: 'student-1', body: 'No access' }, teacher, { authorizedStudentIds: ['student-1'], authorizedParentIds: ['parent-1'] }), /authorized/); });
test('communication announcements, notifications, calendar, and parent preferences are isolated', () => { const service = createCommunicationService(); const parent = { id: 'parent-1', userId: 'parent-1', roleKey: 'PARENT', children: [{ id: 'student-1' }] }; const other = { id: 'parent-2', userId: 'parent-2', roleKey: 'PARENT', children: [{ id: 'student-2' }] }; service.announce({ title: 'PTA', body: 'Meeting', audience: 'SCHOOL' }, { userId: 'admin' }); service.announce({ title: 'Child one', body: 'Private', audience: 'TARGETED', studentIds: ['student-1'] }, { userId: 'admin' }); assert.equal(service.listAnnouncements(parent).length, 2); assert.equal(service.listAnnouncements(other).length, 1); service.notify({ type: 'ABSENCE', recipientId: 'parent-1', studentId: 'student-1', title: 'Absence', body: 'Absent' }); assert.equal(service.listNotifications(parent).length, 1); assert.equal(service.listNotifications(other).length, 0); service.addCalendarEvent({ type: 'PTA', title: 'PTA meeting', startsAt: '2026-09-10' }, { userId: 'admin' }); assert.equal(service.listCalendar(parent).length, 1); assert.equal(service.setPreferences('parent-1', { absence: true, events: false }).events, false); });
