test('operations HTTP routes enforce health privacy server-side', async () => { const auth = createAuthService(); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (path, token) => new Promise((resolve, reject) => { const req = httpRequest({ port, path, headers: { Authorization: `Bearer ${token}` } }, (res) => { res.resume(); res.on('end', () => resolve(res.statusCode)); }); req.on('error', reject); req.end(); }); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); const parent = auth.login({ username: 'parent@example.com', password: 'Parent123!', portal: 'parent' }); assert.equal(await request('/api/welfare/health', teacher.token), 403); assert.equal(await request('/api/welfare/health?studentId=student-1', parent.token), 200); assert.equal(await request('/api/welfare/health?studentId=student-999', parent.token), 403); await new Promise((resolve) => server.close(resolve)); });
test('resources service calculates stock, creates QR assets, and advances procurement', () => { const service = createResourceService(); const storekeeper = { id: 'storekeeper-1' }; const item = service.addInventory({ name: 'Exercise Books', type: 'STATIONERY', reorderLevel: 10 }, storekeeper); service.moveStock({ inventoryId: item.id, type: 'IN', quantity: 20 }, storekeeper); assert.equal(service.list('INVENTORY', { roleKey: 'STOREKEEPER' }).inventory[0].quantity, 20); service.moveStock({ inventoryId: item.id, type: 'OUT', quantity: 5 }, storekeeper); assert.equal(service.list('INVENTORY', { roleKey: 'STOREKEEPER' }).inventory[0].quantity, 15); assert.throws(() => service.moveStock({ inventoryId: item.id, type: 'OUT', quantity: 50 }, storekeeper), /Insufficient/); const asset = service.addAsset({ type: 'COMPUTER', description: 'Laptop', serialNumber: 'SN-1' }, { id: 'property-1' }); assert.match(asset.assetId, /^AST-/); assert.equal(asset.qrCode, 'osaah:asset:1'); assert.throws(() => service.addAsset({ type: 'COMPUTER', description: 'Duplicate', serialNumber: 'SN-1' }, { id: 'property-1' }), /already exists/); const request = service.requestPurchase({ item: 'Projector', quantity: 2 }, { id: 'procurement-1' }); assert.equal(service.advancePurchase(request.id, 'APPROVED', { id: 'headteacher-1' }).state, 'APPROVED'); assert.equal(service.advancePurchase(request.id, 'ORDERED', { id: 'procurement-1' }).state, 'ORDERED'); assert.throws(() => service.advancePurchase(request.id, 'PAID', { id: 'procurement-1' }), /advance in order/); });
