test('compliance service tracks regulatory records, inspections, documents, versions, and exports', () => { const service = createComplianceService(); const officer = { id: 'compliance-1', roleKey: 'COMPLIANCE_OFFICER' }; const record = service.addCompliance({ type: 'NASIA_LICENCE', licenceNumber: 'NASIA-001', expiryDate: '2027-01-01', recommendations: ['Renew'] }, officer); assert.equal(service.addInspection({ complianceId: record.id, rating: 'GOOD' }, officer).rating, 'GOOD'); const document = service.uploadDocument({ category: 'COMPLIANCE', title: 'NaSIA Licence', content: 'certificate', accessRoles: ['COMPLIANCE_OFFICER'] }, officer); assert.match(document.documentNumber, /^DOC-/); assert.equal(service.addVersion(document.id, { content: 'renewed' }, officer).version, 2); assert.equal(service.verifyDocument(document.verificationCode).authentic, true); assert.equal(service.verifyDocument(document.verificationCode).checksum, undefined); assert.ok(service.getDocument(document.id, officer).storageKey); assert.equal(service.list('documents', { roleKey: 'TEACHER' }).length, 0); assert.match(service.exportCensus({ learnerCount: 100 }, 'csv'), /learnerCount/); assert.match(service.privacyNotice().title, /Privacy Notice/); });
test('privacy service records consent, requests, retention, officers, and breaches', () => { const service = createComplianceService(); const dpo = { id: 'dpo-1' }; assert.equal(service.addConsent({ subjectId: 'parent-1', purpose: 'Emergency contact', granted: true }, dpo).granted, true); assert.equal(service.addPrivacyRequest({ type: 'ACCESS', subjectId: 'parent-1' }, dpo).status, 'OPEN'); assert.equal(service.addRetention({ dataCategory: 'HEALTH', retentionPeriod: '7 years' }, dpo).actionAfterExpiry, 'REVIEW'); assert.equal(service.addOfficer({ userId: 'dpo-1' }, dpo).designation, 'DATA_PROTECTION_OFFICER'); assert.equal(service.addBreach({ description: 'Test incident' }, dpo).status, 'OPEN'); });
test('compliance sidebar and HTTP privacy boundaries are enforced', async () => { const compliance = visibleSidebar({ permissions: new Set(['compliance.read', 'documents.read']), roleKey: 'COMPLIANCE_OFFICER' }); assert.ok(compliance.find((group) => group.category === 'COMPLIANCE & DOCUMENTS')?.modules.some((module) => module.moduleKey === 'compliance')); const privacy = visibleSidebar({ permissions: new Set(['privacy.read']), roleKey: 'DATA_PROTECTION_OFFICER' }); assert.ok(privacy.find((group) => group.category === 'SYSTEM & SECURITY')?.modules.some((module) => module.moduleKey === 'privacy')); const auth = createAuthService(); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (path, token) => new Promise((resolve, reject) => { const req = httpRequest({ port, path, headers: { Authorization: `Bearer ${token}` } }, (res) => { res.resume(); res.on('end', () => resolve(res.statusCode)); }); req.on('error', reject); req.end(); }); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); const dpo = auth.login({ username: 'dpo@osaah.edu.gh', password: 'DataProtection123!', portal: 'school' }); assert.equal(await request('/api/compliance', teacher.token), 403); assert.equal(await request('/api/privacy', teacher.token), 403); assert.equal(await request('/api/privacy', dpo.token), 200); await new Promise((resolve) => server.close(resolve)); });
