test('PWA shell, mobile safeguards, retry queue, and dashboard escaping are present', async () => { const html = await readFile(new URL('../public/index.html', import.meta.url), 'utf8'); const manifest = await readFile(new URL('../public/manifest.webmanifest', import.meta.url), 'utf8'); const worker = await readFile(new URL('../public/sw.js', import.meta.url), 'utf8'); const app = await readFile(new URL('../public/app.js', import.meta.url), 'utf8'); const css = await readFile(new URL('../public/styles.css', import.meta.url), 'utf8'); assert.match(html, /manifest\.webmanifest/); assert.match(manifest, /"display":"standalone"/); assert.match(manifest, /osaah-daylight-logo\.png/); assert.match(worker, /url\.pathname\.startsWith\('\/api\/'\)/); assert.match(app, /escapeHtml/); assert.match(app, /serviceWorker\.register/); assert.match(app, /queueServerRequest/); assert.match(app, /retryable === true/); assert.match(css, /@media\(max-width:759px\)/); assert.match(css, /overflow-x:hidden/); assert.match(css, /min-height:44px/); });
test('automatic placement classifies, sorts, nests, deduplicates, and filters modules', () => { const modules = []; const duplicates = []; registerModule({ moduleId: 'staff-leave', moduleName: 'Staff Leave', route: '/staff/non-teaching/leave', priority: 60, requiredPermissions: ['staff.leave.view'] }, modules, { onDuplicate: (...items) => duplicates.push(items) }); registerModule({ moduleId: 'staff-leave', moduleName: 'Staff Leave Updated', category: 'STAFF MANAGEMENT', route: '/staff/leave', priority: 65, requiredPermission: 'staff.leave.view' }, modules, { onDuplicate: (...items) => duplicates.push(items) }); registerModule({ moduleId: 'vehicle-maintenance', moduleName: 'Vehicle Maintenance', route: '/transport/maintenance', priority: 30 }, modules); registerModule({ moduleId: 'child', moduleName: 'Child', category: 'STAFF MANAGEMENT', parentModule: 'staff-leave', priority: 70 }, modules); registerModule({ moduleId: 'disabled', moduleName: 'Disabled', category: 'STAFF MANAGEMENT', enabled: false }, modules); const groups = visibleSidebar({ modules, permissions: new Set(['staff.leave.view']), roleKey: 'HR_OFFICER' }); assert.equal(duplicates.length, 1); assert.equal(groups.find((group) => group.category === 'STAFF MANAGEMENT').modules[0].moduleKey, 'staff-leave'); assert.equal(groups.find((group) => group.category === 'STAFF MANAGEMENT').modules[0].children[0].moduleKey, 'child'); assert.equal(groups.find((group) => group.category === 'TRANSPORT MANAGEMENT').modules[0].moduleKey, 'vehicle-maintenance'); assert.equal(groups.some((group) => group.category === 'LOGOUT'), false); });
