test('classification registry exposes stable IDs and deterministic future component placement', () => { assert.deepEqual(SIDEBAR_CATEGORY_REGISTRY.map((category) => category.categoryId), ['administrative', 'students_management', 'admissions', 'academics', 'attendance_management', 'examinations_results', 'fee_hub', 'finance', 'staff_management', 'communication_hub', 'library_management', 'transport_management', 'hostel_management', 'health_welfare', 'inventory_stores', 'assets_property', 'procurement', 'compliance_documents', 'reports_analytics', 'system_security']); const cases = [['Student Scholarship Management', 'fee_hub'], ['Teacher Professional Development', 'staff_management'], ['Bus Route Tracking', 'transport_management'], ['Student Dormitory Allocation', 'hostel_management'], ['School Asset QR Scanner', 'assets_property'], ['Student Welfare Case Management', 'health_welfare'], ['School Inspection Tracker', 'compliance_documents'], ['Academic Performance Analytics', 'reports_analytics'], ['User Security Dashboard', 'system_security'], ['Online Admission Interview', 'admissions'], ['Digital Lesson Planner', 'academics'], ['Attendance Analytics', 'attendance_management']]; for (const [moduleName, categoryId] of cases) assert.equal(classifyComponent({ moduleId: moduleName.toLowerCase().replaceAll(' ', '-'), moduleName, route: `/${moduleName.toLowerCase().replaceAll(' ', '-')}` }).categoryId, categoryId); });
test('classification respects explicit domain, parent modules, ambiguity diagnostics, and validation', () => { assert.equal(classifyComponent({ moduleId: 'custom', moduleName: 'Custom', feature_domain: 'finance', route: '/custom' }).categoryId, 'finance'); assert.equal(classifyComponent({ moduleId: 'child', moduleName: 'Child', parent_module_key: 'fee-structure', route: '/custom' }).categoryId, 'fee_hub'); const diagnostics = []; const ambiguous = classifyComponent({ moduleId: 'unknown', moduleName: 'Workspace', route: '/workspace' }, { onDiagnostic: (diagnostic) => diagnostics.push(diagnostic) }); assert.equal(ambiguous.categoryId, 'administrative'); assert.equal(diagnostics[0].type, 'AMBIGUOUS_MODULE_CLASSIFICATION'); assert.throws(() => registerComponent({ moduleId: 'invalid', moduleName: 'Invalid', category: 'NOT_A_CATEGORY', route: '/invalid' }), /Invalid sidebar category/); assert.ok(validateSidebarRegistry([{ moduleKey: 'bad', moduleName: 'Bad', category: 'ADMINISTRATIVE', route: '/bad', enabled: true, roles: ['TEACHER'] }]).some((error) => error.type === 'MISSING_PERMISSION')); });
