test('role-based sidebar suggestions and portal boundaries are enforced', () => { assert.ok(DEFAULT_CATEGORY_ROLES.fee_hub.includes('ACCOUNTANT_BURSAR')); assert.ok(DEFAULT_CATEGORY_ROLES.academics.includes('TEACHER')); const teacher = visibleSidebar({ permissions: new Set(['academics.read', 'attendance.read', 'examinations.read', 'communication.read']), roleKey: 'TEACHER', portal: 'school' }); const teacherKeys = teacher.flatMap((group) => group.modules.map((module) => module.moduleKey)); assert.ok(teacherKeys.includes('academics')); assert.ok(teacherKeys.includes('attendance-dashboard')); assert.ok(!teacherKeys.includes('fees')); assert.ok(!teacherKeys.includes('health-records')); const parent = visibleSidebar({ permissions: new Set(['children.read', 'communication.read', 'messages.read', 'calendar.read', 'library.read', 'transport.read', 'hostel.read', 'discipline.read']), roleKey: 'PARENT', portal: 'parent' }); const parentKeys = parent.flatMap((group) => group.modules.map((module) => module.moduleKey)); assert.ok(parentKeys.includes('dashboard')); assert.ok(parentKeys.includes('announcements')); assert.ok(!parentKeys.includes('academics')); assert.ok(!parentKeys.includes('settings')); const student = visibleSidebar({ permissions: new Set(['children.read']), roleKey: 'STUDENT', portal: 'student' }); assert.equal(student.some((group) => group.category !== 'LOGOUT'), false); });
test('proprietor oversight still requires permissions for sensitive categories', () => { const limited = visibleSidebar({ permissions: new Set(['users.read', 'health.read']), roleKey: 'PROPRIETOR', portal: 'school' }); assert.ok(limited.some((group) => group.modules.some((module) => module.moduleKey === 'health-records'))); const noHealth = visibleSidebar({ permissions: new Set(['users.read']), roleKey: 'PROPRIETOR', portal: 'school' }); assert.equal(noHealth.some((group) => group.modules.some((module) => module.moduleKey === 'health-records')), false); });
test('protected pages reject unauthorized direct navigation', async () => { const auth = createAuthService(); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (path, token) => new Promise((resolve, reject) => { const headers = token ? { Authorization: `Bearer ${token}` } : {}; const req = httpRequest({ port, path, headers }, (res) => { res.resume(); res.on('end', () => resolve(res.statusCode)); }); req.on('error', reject); req.end(); }); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); const parent = auth.login({ username: 'parent@example.com', password: 'Parent123!', portal: 'parent' }); assert.equal(await request('/finance', teacher.token), 403); assert.equal(await request('/students', parent.token), 403); assert.equal(await request('/finance'), 401); assert.equal(await request('/attendance', teacher.token), 200); await new Promise((resolve) => server.close(resolve)); });
test('sidebar health diagnostics are server-protected', async () => { const auth = createAuthService(); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (token) => new Promise((resolve, reject) => { const req = httpRequest({ port, path: '/api/sidebar/health', headers: { Authorization: `Bearer ${token}` } }, (res) => { let body = ''; res.on('data', (chunk) => { body += chunk; }); res.on('end', () => resolve({ status: res.statusCode, body })); }); req.on('error', reject); req.end(); }); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); const proprietor = auth.login({ username: 'proprietor@osaah.edu.gh', password: 'Proprietor123!', portal: 'school' }); assert.equal((await request(teacher.token)).status, 403); const result = await request(proprietor.token); assert.equal(result.status, 200); assert.equal(JSON.parse(result.body).totalCategories, 20); await new Promise((resolve) => server.close(resolve)); });
test('all required roles receive only their authorized navigation surfaces', () => { const cases = [
  ['PROPRIETOR', 'school', ['*'], 'SYSTEM & SECURITY'], ['HEADTEACHER', 'school', ['academics.read'], 'ACADEMICS'], ['TEACHER', 'school', ['academics.read'], 'ACADEMICS'],
  ['ACCOUNTANT_BURSAR', 'school', ['fees.read'], 'FEE HUB'], ['ADMISSIONS_OFFICER', 'school', ['admissions.read'], 'ADMISSIONS'], ['LIBRARIAN', 'school', ['library.read'], 'LIBRARY MANAGEMENT'],
  ['TRANSPORT_MANAGER', 'school', ['transport.read'], 'TRANSPORT MANAGEMENT'], ['HOSTEL_MANAGER_MATRON', 'school', ['hostel.read'], 'HOSTEL MANAGEMENT'], ['HR_OFFICER', 'school', ['staff.read'], 'STAFF MANAGEMENT'],
  ['PARENT', 'parent', ['communication.read'], 'COMMUNICATION HUB'], ['STUDENT', 'student', ['*'], null]
]; for (const [roleKey, portal, permissions, expectedCategory] of cases) { const groups = visibleSidebar({ roleKey, portal, permissions: new Set(permissions) }); if (expectedCategory) assert.ok(groups.some((group) => group.category === expectedCategory), `${roleKey} should receive ${expectedCategory}`); assert.equal(groups.some((group) => group.category === 'FINANCE') && !['PROPRIETOR', 'ACCOUNTANT_BURSAR'].includes(roleKey), false, `${roleKey} must not receive finance`); } });
test('future modules auto-register category, parent, permission, priority, and mobile navigation', () => { const modules = SIDEBAR_MODULES.map((module) => ({ ...module })); const cases = [['students.scholarships', 'Student Scholarship Management', 'fee_hub'], ['staff.training', 'Teacher Training Management', 'staff_management'], ['transport.gps.simulation', 'Transport GPS Tracking', 'transport_management'], ['hostel.visitors', 'Hostel Visitor Management', 'hostel_management'], ['library.search', 'Digital Library Search', 'library_management'], ['health.welfare-cases', 'Student Welfare Case Management', 'health_welfare'], ['procurement.suppliers', 'Supplier Evaluation', 'procurement'], ['compliance.inspections', 'School Inspection Management', 'compliance_documents'], ['finance.reconciliation', 'Payment Reconciliation', 'finance'], ['communication.appointments', 'Parent Appointment Booking', 'communication_hub'], ['academics.lesson-planner', 'Digital Lesson Planner', 'academics'], ['students.alumni', 'Alumni Management', 'students_management'], ['assets.qr-scanner', 'Asset QR Scanner', 'assets_property'], ['communication.emergency', 'Emergency Communication', 'communication_hub'], ['staff.recruitment', 'Staff Recruitment', 'staff_management']]; for (const [moduleKey, moduleName, categoryId] of cases) { const registered = registerFutureModule({ module_key: moduleKey, module_name: moduleName, route: `/${moduleKey.replaceAll('.', '/')}`, mobile_enabled: true }, { modules }); assert.equal(registered.categoryId, categoryId); assert.equal(registered.requiredPermission, `${moduleKey}.view`); assert.ok(registered.suggestedRoles.length); assert.equal(registered.mobileVisible, true); } assert.equal(modules.length, SIDEBAR_MODULES.length + cases.length); assert.ok(modules.find((module) => module.moduleKey === 'transport.gps').priority > 10); });
test('future registration blocks unknown production features and exposes navigation diagnostics', () => { const diagnostics = []; const modules = []; const unknown = classifyComponent({ moduleKey: 'workspace.new', moduleName: 'Workspace', route: '/workspace' }, { modules, onDiagnostic: (entry) => diagnostics.push(entry) }); assert.equal(unknown.classificationStatus, 'UNCLASSIFIED'); assert.equal(unknown.classificationWarning.includes('production'), true); assert.throws(() => registerFutureModule({ moduleKey: 'workspace.new', moduleName: 'Workspace', route: '/workspace' }, { modules, onDiagnostic: (entry) => diagnostics.push(entry) }), /Unclassified sidebar module/); assert.ok(diagnostics.some((entry) => entry.type === 'UNCLASSIFIED_MODULE_BLOCKED')); const health = sidebarHealth({ modules: [{ moduleKey: 'disabled', moduleName: 'Disabled', category: 'ADMINISTRATIVE', route: '/disabled', enabled: false }] }); assert.equal(health.totalCategories, 20); assert.deepEqual(health.disabledModules, ['disabled']); });
test('registry supplies breadcrumbs and page metadata for future modules', () => { const modules = SIDEBAR_MODULES.map((module) => ({ ...module })); const registered = registerFutureModule({ moduleKey: 'transport.gps', moduleName: 'GPS Tracking', route: '/transport/gps', feature_domain: 'transport_management', parent_module_key: 'transport' }, { modules }); const breadcrumb = buildBreadcrumb(registered.route, modules); assert.deepEqual(breadcrumb.map((item) => item.label), ['TRANSPORT MANAGEMENT', 'Transport', 'GPS Tracking']); assert.equal(modulePageMetadata(registered.route, modules).title, 'GPS Tracking | OsaaH Daylight'); });
test('registry enforcement catches duplicate routes, invalid roles, and orphan parents', async () => { const modules = [{ moduleKey: 'one', moduleName: 'One', category: 'ACADEMICS', route: '/same', requiredPermission: 'one.view', roles: ['TEACHER'] }, { moduleKey: 'two', moduleName: 'Two', category: 'ACADEMICS', route: '/same', requiredPermission: 'two.view', roles: ['NOT_A_ROLE'], parentModule: 'missing' }]; const errors = validateSidebarRegistry(modules, { strictRoutes: true }); assert.ok(errors.some((error) => error.type === 'DUPLICATE_ROUTE')); assert.ok(errors.some((error) => error.type === 'UNAUTHORIZED_ROLE')); assert.ok(errors.some((error) => error.type === 'INVALID_PARENT')); const guide = await readFile(new URL('../docs/sidebar-registry.md', import.meta.url), 'utf8'); assert.match(guide, /MUST BE REGISTERED THROUGH THE SIDEBAR MODULE REGISTRY/); assert.match(guide, /registerFutureModule/); });
test('parent dashboard shortcuts use registry metadata instead of a duplicate navigation list', () => { const cards = parentDashboardModules(); assert.deepEqual(cards.map((module) => module.moduleName), ['Attendance', 'Results', 'Fees', 'Payments', 'Timetable', 'Homework', 'Assignments', 'Announcements', 'Calendar', 'Messages', 'Transport', 'Documents']); assert.equal(visibleSidebar({ permissions: new Set(['children.read']), roleKey: 'PARENT', portal: 'parent' }).flatMap((group) => group.modules).some((module) => module.parentDashboard), false); });
test('student scholarships register automatically under Fee Hub with requested RBAC', () => { const fee = visibleSidebar({ permissions: new Set(['fees.read', 'fee.scholarships.view']), roleKey: 'ACCOUNTANT_BURSAR', portal: 'school' }).find((group) => group.category === 'FEE HUB'); const parent = fee.modules.find((module) => module.moduleKey === 'fee-structure'); assert.equal(parent.children.find((module) => module.moduleKey === 'fee.scholarships').requiredPermission, 'fee.scholarships.view'); assert.deepEqual(SIDEBAR_MODULES.find((module) => module.moduleKey === 'fee.scholarships').suggestedRoles, ['ACCOUNTANT_BURSAR', 'SCHOOL_ADMIN', 'PROPRIETOR', 'HEADTEACHER']); assert.equal(visibleSidebar({ permissions: new Set(['fees.read', 'fee.scholarships.view']), roleKey: 'TEACHER', portal: 'school' }).some((group) => group.category === 'FEE HUB'), false); });
test('student scholarships route is protected by the same registry authorization', async () => { const auth = createAuthService(); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (token) => new Promise((resolve, reject) => { const req = httpRequest({ port, path: '/fees/scholarships', headers: { Authorization: `Bearer ${token}` } }, (res) => { res.resume(); res.on('end', () => resolve(res.statusCode)); }); req.on('error', reject); req.end(); }); const bursar = auth.login({ username: 'bursar@osaah.edu.gh', password: 'Bursar123!', portal: 'school' }); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); assert.equal(await request(bursar.token), 200); assert.equal(await request(teacher.token), 403); await new Promise((resolve) => server.close(resolve)); });
test('transport GPS tracking registers under Transport Management with protected route access', async () => { const module = SIDEBAR_MODULES.find((item) => item.moduleKey === 'transport.gps'); assert.equal(module.categoryId, 'transport_management'); assert.equal(module.parentModule, 'transport'); assert.equal(module.requiredPermission, 'transport.gps.view'); const transportGroup = visibleSidebar({ permissions: new Set(['transport.read', 'transport.gps.view']), roleKey: 'TRANSPORT_MANAGER', portal: 'school' }).find((group) => group.category === 'TRANSPORT MANAGEMENT'); assert.ok(transportGroup.modules.find((item) => item.moduleKey === 'transport').children.some((item) => item.moduleKey === 'transport.gps')); const auth = createAuthService(); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (token) => new Promise((resolve, reject) => { const req = httpRequest({ port, path: '/transport/gps', headers: { Authorization: `Bearer ${token}` } }, (res) => { res.resume(); res.on('end', () => resolve(res.statusCode)); }); req.on('error', reject); req.end(); }); const manager = auth.login({ username: 'transport@osaah.edu.gh', password: 'Transport123!', portal: 'school' }); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); assert.equal(await request(manager.token), 200); assert.equal(await request(teacher.token), 403); await new Promise((resolve) => server.close(resolve)); });
test('teacher professional development registers under Staff Management with protected route access', async () => { const module = SIDEBAR_MODULES.find((item) => item.moduleKey === 'staff.professional-development'); assert.equal(module.categoryId, 'staff_management'); assert.equal(module.parentModule, null); assert.equal(module.requiredPermission, 'staff.professional-development.view'); const staffGroup = visibleSidebar({ permissions: new Set(['staff.professional-development.view']), roleKey: 'TEACHER', portal: 'school' }).find((group) => group.category === 'STAFF MANAGEMENT'); assert.ok(staffGroup.modules.some((item) => item.moduleKey === 'staff.professional-development')); assert.equal(staffGroup.modules.some((item) => item.moduleKey === 'staff-directory'), false); const auth = createAuthService(); const server = createServer(createApp({ auth })); await new Promise((resolve) => server.listen(0, resolve)); const port = server.address().port; const request = (token) => new Promise((resolve, reject) => { const req = httpRequest({ port, path: '/staff/professional-development', headers: { Authorization: `Bearer ${token}` } }, (res) => { res.resume(); res.on('end', () => resolve(res.statusCode)); }); req.on('error', reject); req.end(); }); const teacher = auth.login({ username: 'teacher@osaah.edu.gh', password: 'Teacher123!', portal: 'school' }); const librarian = auth.login({ username: 'librarian@osaah.edu.gh', password: 'Librarian123!', portal: 'school' }); assert.equal(await request(teacher.token), 200); assert.equal(await request(librarian.token), 403); await new Promise((resolve) => server.close(resolve)); });
